mapper.select:
SELECT COUNT(*)
FROM sprint
WHERE project_id = #{projectId}

SELECT COUNT(*) FROM sprint s WHERE 1=1
AND s.project_id IN
#{pid}

SELECT s.id, s.project_id, p.name AS project_name, p.key AS project_key, s.name, s.goal, s.status, s.start_date, s.end_date, s.created_at, s.started_at, s.start_scope_hours, s.start_scope_issues, COALESCE(stats.total_issues, 0) AS total_issues, COALESCE(stats.done_issues, 0) AS done_issues, COALESCE(stats.in_progress_issues, 0) AS in_progress_issues, COALESCE(stats.todo_issues, 0) AS todo_issues, COALESCE(stats.overdue_issues, 0) AS overdue_issues, COALESCE(stats.unassigned_issues, 0) AS unassigned_issues, COALESCE(stats.total_estimated_hours, 0) AS total_estimated_hours, COALESCE(stats.completed_estimated_hours, 0) AS completed_estimated_hours FROM sprint s JOIN project p ON p.id = s.project_id LEFT JOIN ( SELECT i.sprint_id, COUNT(*) AS total_issues, COUNT(*) FILTER (WHERE ist.is_closed = true) AS done_issues, COUNT(*) FILTER (WHERE ist.is_closed = false AND ist.category = 'in_progress') AS in_progress_issues, COUNT(*) FILTER (WHERE ist.is_closed = false AND ist.category != 'in_progress') AS todo_issues, COUNT(*) FILTER (WHERE ist.is_closed = false AND i.due_date IS NOT NULL AND i.due_date < CURRENT_DATE AND sp.status = 'active') AS overdue_issues, COUNT(*) FILTER (WHERE i.assignee_id IS NULL) AS unassigned_issues, COALESCE(SUM(i.estimated_hours), 0) AS total_estimated_hours, COALESCE(SUM(i.estimated_hours) FILTER (WHERE ist.is_closed = true), 0) AS completed_estimated_hours FROM issue i JOIN sprint sp ON sp.id = i.sprint_id LEFT JOIN issue_status ist ON ist.id = i.status_id WHERE i.deleted_at IS NULL GROUP BY i.sprint_id ) stats ON stats.sprint_id = s.id WHERE 1=1
AND s.project_id IN
#{pid}
ORDER BY CASE s.status WHEN 'active' THEN 1 WHEN 'planned' THEN 2 WHEN 'completed' THEN 3 WHEN 'archived' THEN 4 END, p.key ASC, CASE WHEN s.status = 'planned' THEN s.start_date ELSE NULL END ASC NULLS LAST, CASE WHEN s.status = 'planned' AND s.start_date IS NULL THEN s.end_date ELSE NULL END ASC NULLS LAST, CASE WHEN s.status != 'planned' THEN s.start_date ELSE NULL END DESC NULLS LAST, s.created_at ASC LIMIT #{limit} OFFSET #{offset}

SELECT CAST(i.sprint_id AS VARCHAR) AS sprint_id, CAST(ist.id AS VARCHAR) AS status_id, COALESCE(ist.display_name, ist.name) AS status_name, ist.color AS status_color, ist.category AS category, ist.sort_order AS sort_order, COUNT(*) AS count FROM issue i JOIN issue_status ist ON ist.id = i.status_id WHERE i.deleted_at IS NULL AND i.sprint_id IN
#{sid}
GROUP BY i.sprint_id, ist.id, ist.name, ist.display_name, ist.color, ist.category, ist.sort_order ORDER BY ist.sort_order ASC
